script:
export const meta = {
  name: 'review_loop',
  description: 'Target-aware actor-critic review, fix, re-review, and validation loop',
  phases: [{ title: 'Target' }, { title: 'Converge' }, { title: 'Final Validation' }, { title: 'Report' }],
}

const POLICY = {
  maxRounds: 3,
  reviewers: 2,
  threshold: 0.51,
  severityGate: ['blocker', 'high'],
  chunkTargetLines: { diff: 400, snapshot: 2000 },
  maxChunks: 6,
  maxChunkLines: { diff: 6000, snapshot: 12000 },
  maxFindingsPerLane: 5,
  maxVerifyClaimsPerRound: 8,
  focusedTestMaxCommands: 3,
  fixerTimeoutMs: 900000,
  focusedValidationTimeoutMs: 600000,
  finalValidationTimeoutMs: 1800000,
  consecutiveDryRounds: 2,
  maxFeatureDescriptionChars: 500,
}
const limits = {
  maxRounds: POLICY.maxRounds,
  reviewers: POLICY.reviewers,
  threshold: POLICY.threshold,
  severityGate: POLICY.severityGate.slice(),
  chunkTargetLines: { ...POLICY.chunkTargetLines },
  maxChunks: POLICY.maxChunks,
  maxChunkLines: { ...POLICY.maxChunkLines },
  maxFindingsPerLane: POLICY.maxFindingsPerLane,
  maxVerifyClaimsPerRound: POLICY.maxVerifyClaimsPerRound,
  focusedTestMaxCommands: POLICY.focusedTestMaxCommands,
  fixerTimeoutMs: POLICY.fixerTimeoutMs,
  focusedValidationTimeoutMs: POLICY.focusedValidationTimeoutMs,
  finalValidationTimeoutMs: POLICY.finalValidationTimeoutMs,
}
const routing = {
  critic: { tier: 'criticBig', effective: 'tier:criticBig' },
  fixer: { tier: 'fixerBig', effective: 'tier:fixerBig' },
  verifier: { tier: 'medium', effective: 'tier:medium' },
  discovery: { tier: 'small', effective: 'tier:small' },
  validation: { tier: 'medium', effective: 'tier:medium' },
}
const USAGE = 'Usage: /review-loop [diff [range] | pr <number> | paths <path...> | feature <description...> | repo]'
const hasOwn = (value, key) => Object.prototype.hasOwnProperty.call(value, key)
const uniq = (arr) => {
  const seen = Object.create(null)
  const out = []
  for (const value of arr || []) {
    const key = String(value)
    if (!seen[key]) { seen[key] = true; out.push(value) }
  }
  return out
}
const sumLines = (files) => (files || []).reduce((total, file) => total + (Number(file.lineCount) || 0), 0)
const abortResult = (reason, message, parsedTarget = null) => ({
  verdict: 'ABORTED - ' + message,
  terminationReason: reason,
  parsedTarget,
  targetPlan: null,
  targetManifest: { version: 0, files: [], fileCount: 0, totalLines: 0 },
  discovery: { complete: false, evidence: [], exclusions: [], warnings: [message], disagreements: [] },
  manifestChanges: [],
  roundsRun: 0,
  chunks: 0,
  chunkSummary: [],
  chunkCoverage: [],
  skippedCoverage: { fileCount: 0, lineCount: 0, paths: [] },
  oversizedFiles: [],
  limits,
  routing,
  totalAddressed: 0,
  totalResolved: 0,
  totalFixed: 0,
  unresolved: [],
  verified: [],
  refuted: [],
  unverified: [],
  disputed: [],
  escalated: [],
  tracked: [],
  seriousLedger: [],
  verificationOverflow: [],
  verificationOverflowCount: 0,
  unresolvedVerificationOverflow: [],
  unresolvedVerificationOverflowCount: 0,
  outOfPolicyChanges: [],
  fixerFailure: null,
  trajectory: [],
  missingCriticLanes: [],
  commandTrust: { executionAllowed: false, enforceableIsolation: false, reason: 'Workflow did not reach command trust evaluation.' },
  fixLog: [],
  finalValidation: { status: 'skipped', reason, commands: [], summary: '', failures: [] },
  residualRisk: '',
  report: message + '\n\n' + USAGE,
})

const inputArgs = args && typeof args === 'object' ? args : {}
const allowedArgKeys = { target: true, _: true, _raw: true }
const unknownArgs = Object.keys(inputArgs).filter((key) => !allowedArgKeys[key])
if (unknownArgs.length) {
  return abortResult('unknown-arguments', 'unknown named argument(s): ' + unknownArgs.sort().join(', ') + '. Only target is supported.')
}
const namedPresent = hasOwn(inputArgs, 'target')
if (namedPresent && typeof inputArgs.target !== 'string') {
  return abortResult('invalid-target', 'target must be a string.')
}
if (hasOwn(inputArgs, '_') && typeof inputArgs._ !== 'string') {
  return abortResult('invalid-positional-target', 'the positional target must be a string.')
}
const namedTarget = namedPresent ? inputArgs.target.trim() : ''
const positionalTarget = typeof inputArgs._ === 'string' ? inputArgs._.trim() : ''
if (namedPresent && positionalTarget) {
  return abortResult('conflicting-targets', 'named target and positional target cannot be supplied together.')
}
const rawTarget = namedPresent ? namedTarget : positionalTarget

const REDACTED = '[REDACTED]'
const sanitizeText = (value) => String(value == null ? '' : value)
  .replace(/SECRET_SENTINEL_[A-Za-z0-9_-]+/g, REDACTED)
  .replace(/\b(?:sk|ghp|github_pat|xox[baprs])[-_][A-Za-z0-9_-]{12,}\b/g, REDACTED)
  .replace(/\bAKIA[0-9A-Z]{16}\b/g, REDACTED)
  .replace(/-----BEGIN [^-]+ PRIVATE KEY-----[\s\S]*?-----END [^-]+ PRIVATE KEY-----/g, REDACTED)
  .replace(/\b(password|passwd|token|secret|api[_-]?key)\s*[:=]\s*[^\s,;]+/gi, '$1=' + REDACTED)
const sanitizeValue = (value) => {
  if (typeof value === 'string') return sanitizeText(value)
  if (Array.isArray(value)) return value.map(sanitizeValue)
  if (value && typeof value === 'object') {
    const output = {}
    for (const key of Object.keys(value)) output[key] = sanitizeValue(value[key])
    return output
  }
  return value
}
const normalizeRepoPath = (rawPath) => {
  if (typeof rawPath !== 'string' || !rawPath || rawPath.length > 1000 || /[\0\n\r]/.test(rawPath)) {
    return { valid: false, path: null, reason: 'empty, overlong, or control-character path' }
  }
  const path = rawPath.replace(/\\/g, '/')
  if (path.startsWith('//')) return { valid: false, path: null, reason: 'UNC path' }
  if (path.startsWith('/')) return { valid: false, path: null, reason: 'absolute path' }
  if (/^[A-Za-z]:/.test(path)) return { valid: false, path: null, reason: 'Windows drive path' }
  const parts = path.split('/')
  if (parts.some((part) => !part || part === '.' || part === '..')) {
    return { valid: false, path: null, reason: 'empty, dot, or traversal segment' }
  }
  return { valid: true, path: parts.join('/'), reason: null }
}
const isRepoRelativePath = (path) => normalizeRepoPath(path).valid
const isSafePathSelector = (path) => {
  if (typeof path !== 'string' || path.startsWith('-')) return false
  const normalized = normalizeRepoPath(path)
  return normalized.valid && normalized.path.length <= 500 && /^[A-Za-z0-9._@+/-]+$/.test(normalized.path)
}
const isSafeDiffSelector = (selector) => {
  if (selector === '--staged' || selector === '--cached' || selector === 'HEAD') return true
  if (!selector || selector.length > 200 || selector.startsWith('-')) return false
  return /^[A-Za-z0-9][A-Za-z0-9._/@~^+-]*(?:\.{2,3}[A-Za-z0-9][A-Za-z0-9._/@~^+-]*)?$/.test(selector)
}
const parseTarget = (raw) => {
  const text = String(raw || '').trim()
  if (!text) return { ok: true, value: { raw: '', kind: 'diff', basis: 'diff', mode: 'default', label: 'current branch diff', selector: { mode: 'default' } } }
  const tokens = text.split(/\s+/)
  const mode = tokens[0]
  const rest = tokens.slice(1)
  if (mode === 'diff') {
    if (rest.length === 0) return { ok: true, value: { raw: text, kind: 'diff', basis: 'diff', mode: 'default', label: 'current branch diff', selector: { mode: 'default' } } }
    if (rest.length !== 1 || !isSafeDiffSelector(rest[0])) return { ok: false, reason: 'diff requires one safe Git range or supported selector.' }
    return { ok: true, value: { raw: text, kind: 'diff', basis: 'diff', mode: 'range', label: 'Git diff ' + rest[0], selector: { mode: 'range', range: rest[0] } } }
  }
  if (mode === 'pr') {
    if (rest.length !== 1 || !/^[1-9][0-9]{0,8}$/.test(rest[0])) return { ok: false, reason: 'pr requires one positive pull-request number.' }
    return { ok: true, value: { raw: text, kind: 'pr', basis: 'diff', mode: 'pr', label: 'pull request #' + rest[0], selector: { number: Number(rest[0]) } } }
  }
  if (mode === 'paths') {
    if (!rest.length) return { ok: false, reason: 'paths requires at least one repository-relative file or directory.' }
    const invalid = rest.filter((path) => !isSafePathSelector(path))
    if (invalid.length) return { ok: false, reason: 'paths contains unsafe or malformed selectors: ' + invalid.join(', ') + '.' }
    const normalizedPaths = rest.map((path) => normalizeRepoPath(path).path)
    return { ok: true, value: { raw: text, kind: 'paths', basis: 'snapshot', mode: 'paths', label: 'paths ' + normalizedPaths.join(' '), selector: { paths: uniq(normalizedPaths) } } }
  }
  if (mode === 'feature') {
    const description = rest.join(' ').trim()
    if (!description || description.length > POLICY.maxFeatureDescriptionChars || /[\0\n\r]/.test(description)) {
      return { ok: false, reason: 'feature requires a non-empty single-line description of at most ' + POLICY.maxFeatureDescriptionChars + ' characters.' }
    }
    return { ok: true, value: { raw: text, kind: 'feature', basis: 'snapshot', mode: 'feature', label: 'feature ' + description, selector: { description } } }
  }
  if (mode === 'repo') {
    if (rest.length) return { ok: false, reason: 'repo does not accept additional selectors.' }
    return { ok: true, value: { raw: text, kind: 'repo', basis: 'snapshot', mode: 'repo', label: 'relevant repository codebase', selector: { mode: 'repo' } } }
  }
  return { ok: false, reason: 'unknown target mode "' + mode + '".' }
}
const parsed = parseTarget(rawTarget)
if (!parsed.ok) return abortResult('invalid-target-selector', parsed.reason, { raw: rawTarget })
const parsedTarget = parsed.value
const commandTrust = parsedTarget.kind === 'pr'
  ? {
      executionAllowed: false,
      enforceableIsolation: false,
      classification: 'untrusted-pull-request',
      reason: 'Validation unavailable for untrusted pull-request content: the installed runtime offers only best-effort worktree isolation, not an enforceable host sandbox or restricted tool contract.',
    }
  : {
      executionAllowed: true,
      enforceableIsolation: false,
      classification: 'locally-authorized-target',
      reason: 'Local validation is user-authorized but executes with host privileges; read-only prompt wording and post-run Git inspection are not security boundaries.',
    }

const fileSchema = {
  type: 'object',
  properties: {
    path: { type: 'string' },
    lineCount: { type: 'number' },
    role: { type: 'string' },
    reason: { type: 'string' },
    selected: { type: 'boolean' },
    kind: { type: 'string', enum: ['file', 'symlink', 'other'] },
    resolvedPathContained: { type: 'boolean' },
  },
  required: ['path', 'lineCount', 'role', 'reason', 'selected', 'kind', 'resolvedPathContained'],
}
const exclusionSchema = {
  type: 'object',
  properties: { category: { type: 'string' }, path: { type: 'string' }, reason: { type: 'string' }, count: { type: 'number' } },
  required: ['category', 'reason'],
}
const discoverySchema = {
  type: 'object',
  properties: {
    files: { type: 'array', items: fileSchema },
    exclusions: { type: 'array', items: exclusionSchema },
    coverage: { type: 'object', properties: { complete: { type: 'boolean' }, warnings: { type: 'array', items: { type: 'string' } } }, required: ['complete', 'warnings'] },
    evidence: { type: 'array', items: { type: 'string' } },
    disagreements: { type: 'array', items: { type: 'string' } },
    requestedCoverage: { type: 'array', items: { type: 'object', properties: { request: { type: 'string' }, matchedFiles: { type: 'number' } }, required: ['request', 'matchedFiles'] } },
    trackedRelevantCount: { type: 'number' },
    includedCount: { type: 'number' },
  },
  required: ['files', 'exclusions', 'coverage', 'evidence', 'disagreements'],
}
const normalizeDiscovery = (result, requiredComplete) => {
  if (!result || !Array.isArray(result.files)) return null
  const warnings = result.coverage && Array.isArray(result.coverage.warnings)
    ? result.coverage.warnings.map(sanitizeText)
    : []
  const byPath = Object.create(null)
  for (const rawFile of result.files) {
    const normalizedPath = rawFile && normalizeRepoPath(rawFile.path)
    if (!rawFile || !normalizedPath.valid || !Number.isFinite(rawFile.lineCount) || rawFile.lineCount < 0) {
      warnings.push('Rejected unsafe or malformed discovered file entry.')
      continue
    }
    const kind = ['file', 'symlink', 'other'].includes(rawFile.kind) ? rawFile.kind : 'other'
    const resolvedPathContained = rawFile.resolvedPathContained === true
    const file = {
      path: normalizedPath.path,
      lineCount: Math.floor(rawFile.lineCount),
      role: sanitizeText(rawFile.role || 'implementation'),
      reason: sanitizeText(rawFile.reason || 'Included by target discovery.'),
      selected: rawFile.selected === true,
      kind,
      resolvedPathContained,
      mutationSafe: kind === 'file' || (kind === 'symlink' && resolvedPathContained),
    }
    if (kind === 'symlink' && !resolvedPathContained) {
      warnings.push('Symlink path ' + file.path + ' is reviewable but not mutation-authorized because resolved-path containment was not proven.')
    } else if (kind === 'other') {
      warnings.push('File kind for ' + file.path + ' was not established as a regular file or contained symlink; mutation is prohibited.')
    }
    const prior = byPath[file.path]
    if (!prior || (!prior.selected && file.selected)) byPath[file.path] = file
  }
  const files = Object.keys(byPath).sort().map((path) => byPath[path])
  let complete = Boolean(result.coverage && result.coverage.complete)
  if (requiredComplete && warnings.some((warning) => !/^Symlink path /.test(warning))) complete = false
  const exclusions = Array.isArray(result.exclusions) ? result.exclusions.map((entry) => sanitizeValue(entry)) : []
  return {
    files,
    exclusions,
    coverage: { complete, warnings: uniq(warnings) },
    evidence: Array.isArray(result.evidence) ? result.evidence.map(sanitizeText) : [],
    disagreements: Array.isArray(result.disagreements) ? result.disagreements.map(sanitizeText) : [],
    requestedCoverage: Array.isArray(result.requestedCoverage) ? result.requestedCoverage.map((entry) => sanitizeValue(entry)) : [],
    trackedRelevantCount: Number.isFinite(result.trackedRelevantCount) ? Math.floor(result.trackedRelevantCount) : null,
    includedCount: Number.isFinite(result.includedCount) ? Math.floor(result.includedCount) : files.length,
  }
}

phase('Target')
let rawDiscovery = null
let discoveryRuns = []
if (parsedTarget.kind === 'feature') {
  const description = parsedTarget.selector.description
  const perspectives = await parallel([
    () => agent(
      'Discover the COMPLETE CURRENT implementation surface for this feature, independent of Git history: ' + JSON.stringify(description) + '. ' +
      'Use a structure-first perspective: repository search, entry points, implementation modules, callers/consumers, types/schemas, configuration, persistence boundaries, direct dependencies, and tests. ' +
      'Use read-only tools only. Inventory tracked current files, read complete contents as needed, and compute each full-file line count deterministically. ' +
      'Return a declarative manifest only; never return shell commands. Mark uncertainty and missing coverage honestly. Never quote secret values; redact them.',
      { tier: 'small', label: 'feature discover structure', schema: discoverySchema, retries: 1 }),
    () => agent(
      'Independently discover the COMPLETE CURRENT implementation surface for this feature, independent of Git history: ' + JSON.stringify(description) + '. ' +
      'Use a behavior-first perspective: trace user-visible flows, runtime call paths, tests, configuration flags, schemas/types, storage and network boundaries, consumers, and failure paths. ' +
      'Use read-only tools only. Inventory tracked current files, read complete contents as needed, and compute each full-file line count deterministically. ' +
      'Return a declarative manifest only; never return shell commands. Mark uncertainty and missing coverage honestly. Never quote secret values; redact them.',
      { tier: 'small', label: 'feature discover behavior', schema: discoverySchema, retries: 1 }),
  ])
  discoveryRuns = [
    { perspective: 'structure', status: perspectives[0] ? 'completed' : 'missing', result: perspectives[0] ? sanitizeValue(perspectives[0]) : null },
    { perspective: 'behavior', status: perspectives[1] ? 'completed' : 'missing', result: perspectives[1] ? sanitizeValue(perspectives[1]) : null },
  ]
  rawDiscovery = await agent(
    'Reconcile two independent feature discovery manifests into one complete current feature target. Preserve evidence, file roles/reasons, exclusions, warnings, and every disagreement. ' +
    'Union supported entry points, implementations, callers/consumers, tests, configuration, schemas/types, persistence boundaries, and direct dependencies. ' +
    'Read complete current files and verify full-file line counts with read-only operations where manifests differ. ' +
    'For every reconciled file, mechanically confirm it is a tracked repository file with read-only git ls-files and record one requestedCoverage entry per path (request=path, matchedFiles>=1) as existence proof; any path without such proof is unproven and keeps coverage incomplete. ' +
    'Set coverage.complete=false if either discovery is missing, disagreements remain material, existence cannot be mechanically proven, or complete semantic coverage cannot be established. Return no shell command and never quote secret values.\n\n' +
    JSON.stringify(sanitizeValue({ target: parsedTarget, discoveries: discoveryRuns })),
    { tier: 'small', label: 'feature reconcile', schema: discoverySchema, retries: 1 })
} else {
  let prompt = ''
  if (parsedTarget.kind === 'diff' && parsedTarget.mode === 'default') {
    prompt = 'Inventory the current branch diff using deterministic read-only Git data. Resolve the real default branch from repository/remotes, use the current branch versus its merge base, then fall back to staged changes, then HEAD exactly in that order. Use numstat for added+removed changed-line counts. Return only a declarative file manifest and evidence identifying which fallback was selected; never return a command. Exclude binary entries explicitly.'
  } else if (parsedTarget.kind === 'diff') {
    prompt = 'Inventory the explicit validated Git diff selector ' + JSON.stringify(parsedTarget.selector.range) + ' using deterministic read-only Git numstat. lineCount is added+removed changed lines. Return only a declarative file manifest; never return a command. Exclude binary entries explicitly.'
  } else if (parsedTarget.kind === 'pr') {
    prompt = 'Inventory pull request #' + parsedTarget.selector.number + ' with read-only GitHub/Git operations and deterministic numstat-equivalent added+removed changed-line counts. Validate that the PR exists and belongs to this repository. Return only a declarative file manifest; never return a command. Exclude binary entries explicitly.'
  } else if (parsedTarget.kind === 'paths') {
    prompt = 'Resolve these validated repository-relative tracked path selectors with git ls-files: ' + JSON.stringify(parsedTarget.selector.paths) + '. Expand directories recursively. Include every relevant selected tracked file and nearby tests only when needed for understanding; distinguish selected files from contextual files with selected and role. Read COMPLETE CURRENT contents and compute full-file line counts deterministically. Every request must have a requestedCoverage entry. Empty or unmatched selectors are incomplete. Return only a declarative manifest; never return a command.'
  } else {
    prompt = 'Inventory ALL relevant tracked repository source, tests, build files, and configuration using deterministic git ls-files data. Read COMPLETE CURRENT contents and compute full-file line counts deterministically. Exclude generated, vendored, binary, cache, dependency, and other non-reviewable artifacts, and report every exclusion category with counts/reasons. trackedRelevantCount and includedCount must permit completeness auditing. Return only a declarative manifest; never return a command.'
  }
  prompt += ' Never quote credential or secret values; redact them while preserving paths and structural evidence.'
  rawDiscovery = await agent(prompt, { tier: 'small', label: 'discover ' + parsedTarget.kind, schema: discoverySchema, retries: 1 })
  rawDiscovery = rawDiscovery ? sanitizeValue(rawDiscovery) : null
  discoveryRuns = [{ perspective: parsedTarget.kind, status: rawDiscovery ? 'completed' : 'missing', result: rawDiscovery || null }]
}

const normalized = normalizeDiscovery(rawDiscovery, true)
if (!normalized) return abortResult('target-discovery-failed', 'could not resolve a declarative target manifest.', parsedTarget)
if (parsedTarget.kind === 'feature') {
  const perspectiveManifests = discoveryRuns.map((run) => normalizeDiscovery(run.result, false))
  const missingPerspective = discoveryRuns.some((run) => run.status !== 'completed') || perspectiveManifests.some((manifest) => !manifest)
  const incompletePerspective = perspectiveManifests.some((manifest) => manifest && manifest.coverage.complete !== true)
  const unionByPath = Object.create(null)
  for (const manifest of perspectiveManifests.filter(Boolean)) {
    for (const file of manifest.files) {
      const prior = unionByPath[file.path]
      if (!prior) unionByPath[file.path] = file
      else if (prior.lineCount !== file.lineCount || prior.role !== file.role || prior.kind !== file.kind) {
        normalized.disagreements.push('Conflicting discovery metadata for ' + file.path + ': line count, role, or file kind differs between perspectives.')
      }
    }
  }
  const reconciledByPath = Object.create(null)
  for (const file of normalized.files) reconciledByPath[file.path] = file
  const excludedPaths = Object.create(null)
  for (const exclusion of normalized.exclusions) {
    const exclusionPath = exclusion && normalizeRepoPath(exclusion.path)
    if (exclusionPath.valid && sanitizeText(exclusion.reason)) excludedPaths[exclusionPath.path] = true
  }
  for (const path of Object.keys(unionByPath).sort()) {
    if (!reconciledByPath[path] && !excludedPaths[path]) {
      normalized.files.push(unionByPath[path])
      reconciledByPath[path] = unionByPath[path]
      normalized.coverage.complete = false
      normalized.coverage.warnings.push('Feature reconciler omitted discovered union path: ' + path + '.')
    }
  }
  normalized.files.sort((left, right) => left.path < right.path ? -1 : (left.path > right.path ? 1 : 0))
  normalized.disagreements = uniq(normalized.disagreements)
  const featureExistenceProven = Object.create(null)
  for (const entry of normalized.requestedCoverage) {
    const provenPath = entry && normalizeRepoPath(entry.request)
    if (provenPath && provenPath.valid && Number(entry.matchedFiles) > 0) featureExistenceProven[provenPath.path] = true
  }
  const unprovenFeaturePaths = normalized.files.filter((file) => !featureExistenceProven[file.path]).map((file) => file.path)
  if (unprovenFeaturePaths.length) {
    normalized.coverage.complete = false
    normalized.coverage.warnings.push('Feature discovery did not mechanically confirm tracked existence via git ls-files for: ' + unprovenFeaturePaths.join(', ') + '.')
  }
  if (missingPerspective || incompletePerspective || normalized.disagreements.length) {
    normalized.coverage.complete = false
    if (missingPerspective) normalized.coverage.warnings.push('One or more independent feature discovery perspectives are missing.')
    if (incompletePerspective) normalized.coverage.warnings.push('One or more independent feature discovery perspectives reported incomplete coverage.')
    if (normalized.disagreements.length) normalized.coverage.warnings.push('Material feature discovery disagreements remain unresolved.')
  }
  normalized.coverage.warnings = uniq(normalized.coverage.warnings)
}
if (parsedTarget.kind === 'paths') {
  const coverageByRequest = Object.create(null)
  for (const entry of normalized.requestedCoverage) coverageByRequest[entry.request] = entry.matchedFiles
  const unmatched = parsedTarget.selector.paths.filter((path) => !(coverageByRequest[path] > 0))
  const outsideSelection = normalized.files.filter((file) => file.selected && !parsedTarget.selector.paths.some((path) => file.path === path || file.path.startsWith(path + '/')))
  if (unmatched.length) return abortResult('path-resolution-failed', 'path selector(s) did not resolve to relevant tracked files: ' + unmatched.join(', ') + '.', parsedTarget)
  if (outsideSelection.length) return abortResult('path-resolution-failed', 'path discovery returned selected files outside the requested paths.', parsedTarget)
}
if (parsedTarget.kind === 'repo') {
  if (normalized.trackedRelevantCount === null || normalized.includedCount !== normalized.files.length || normalized.trackedRelevantCount !== normalized.files.length) {
    normalized.coverage.complete = false
    normalized.coverage.warnings.push('Repository inventory counts do not prove that every relevant tracked file is included.')
  }
}
const compactDiscoveryRuns = discoveryRuns.map((run) => {
  const runManifest = normalizeDiscovery(run.result, false)
  return {
    perspective: run.perspective,
    status: run.status,
    coverageComplete: Boolean(runManifest && runManifest.coverage.complete),
    paths: runManifest ? runManifest.files.map((file) => file.path) : [],
    warnings: runManifest ? runManifest.coverage.warnings : ['Discovery perspective returned no result.'],
  }
})
if (!normalized.files.length) {
  if (parsedTarget.basis === 'diff' && normalized.coverage.complete === true) {
    return {
      ...abortResult('no-changes', 'NO CHANGES TO REVIEW', parsedTarget),
      verdict: 'NO CHANGES TO REVIEW',
      terminationReason: 'no-changes',
      targetPlan: { kind: parsedTarget.kind, basis: parsedTarget.basis, label: parsedTarget.label, selector: parsedTarget.selector, files: [], exclusions: normalized.exclusions, coverage: normalized.coverage },
      discovery: { ...normalized, complete: true, runs: compactDiscoveryRuns },
      commandTrust,
      report: 'NO CHANGES TO REVIEW for ' + parsedTarget.label + '.',
    }
  }
  if (parsedTarget.basis === 'diff') {
    const result = abortResult('incomplete-empty-discovery', 'empty diff discovery is incomplete and cannot establish that there are no changes.', parsedTarget)
    result.discovery = { ...normalized, complete: false, runs: compactDiscoveryRuns }
    result.commandTrust = commandTrust
    return result
  }
  return abortResult('empty-target-manifest', 'target discovery produced no reviewable files.', parsedTarget)
}

let targetPlan = {
  kind: parsedTarget.kind,
  basis: parsedTarget.basis,
  label: parsedTarget.label,
  selector: parsedTarget.selector,
  files: normalized.files,
