  let unverifiedThisRound = 0
  let escalatedThisRound = 0
  verificationQueue.forEach((finding, index) => {
    const check = checks[index]
    const covered = check && typeof check.total === 'number' ? check.total : 0
    if (!check || covered < POLICY.reviewers) {
      setClaimStatus(finding, 'unverified', roundsRun, 'Verifier coverage was incomplete.')
      resolveOverflow(finding.claimId, 'unverified', roundsRun)
      unverifiedThisRound++
      return
    }
    if (!check.real) {
      if (check.realCount > 0) {
        setClaimStatus(finding, 'disputed', roundsRun, 'Verifier panel split; no tie-resolution policy is configured.')
        resolveOverflow(finding.claimId, 'disputed', roundsRun)
        disputedThisRound++
      } else {
        setClaimStatus(finding, 'refuted', roundsRun, 'All completed verifiers refuted the claim.')
        resolveOverflow(finding.claimId, 'refuted', roundsRun)
        refutedThisRound++
      }
      return
    }
    const ledger = registerSeriousClaim(finding, roundsRun)
    ledger.everVerified = true
    addressedClaimIds[finding.claimId] = true
    verifiedThisRound++
    const decision = mutationDecision(finding)
    finding.mutationEligible = decision.eligible
    finding.mutationReason = decision.reason
    if (!decision.eligible) {
      setClaimStatus(finding, 'escalated', roundsRun, decision.reason)
      resolveOverflow(finding.claimId, 'escalated', roundsRun)
      escalatedThisRound++
    } else {
      fixable.push(finding)
      ledger.status = 'verified'
      ledger.reason = 'Verified and awaiting a specifically bound fix.'
    }
  })

  const unresolvedSeriousThisRound = overflowFindings.length > 0 || verificationQueue.some((finding) => {
    const status = seriousClaims[finding.claimId].status
    return status !== 'refuted' && status !== 'fixed-and-validated'
  })
  if (!fixable.length) {
    const globallyUnresolvedSerious = Object.values(seriousClaims).some((entry) => !['refuted', 'fixed-and-validated'].includes(entry.status))
    const genuinelyDry = !unresolvedSeriousThisRound && !globallyUnresolvedSerious && lanesOk === totalLanes && totalLanes > 0 && everyFileAssigned
    noteRoundDryness(genuinelyDry, reviewedManifestVersion)
    trajectory.push({
      round: roundsRun, manifestVersion: reviewedManifestVersion, manifestVersionAfter: manifestVersion, chunks: roundChunkSummary,
      lanesOk, totalLanes, missingCoverage, everyFileAssigned, genuinelyDry, findings: allFindings.length,
      gatedRaw: seriousRaw.length, gated: serious.length, deduplicatedBeforeVerify: seriousRaw.length - serious.length,
      verificationClaims: verificationQueue.length, verificationOverflowCount: overflowFindings.length, verificationOverflow: overflowFindings,
      verified: verifiedThisRound, refuted: refutedThisRound, disputed: disputedThisRound, unverified: unverifiedThisRound,
      escalated: escalatedThisRound, fixesRequested: 0, fixes: [], changedFiles: [], testsChanged: [], manifestChanges: [],
      focusedValidation: { status: 'not_run', commands: [], checkedFindingIds: [], notes: 'No mutation-eligible verified findings this round.' },
    })
    if (convergedDry >= POLICY.consecutiveDryRounds) terminationReason = 'consecutive-clean-rounds'
    continue
  }

  noteRoundDryness(false, reviewedManifestVersion)
  const fixerPayload = {
    target: { kind: parsedTarget.kind, basis: parsedTarget.basis, selector: parsedTarget.selector, manifestVersion: reviewedManifestVersion },
    authorizedExistingPaths: manifestFiles.filter((file) => file.mutationSafe !== false).map((file) => file.path),
    findings: fixable.map(compactFindingForMutation),
  }
  const fixResult = await agent(
    'You are the fixer. Apply minimal fixes only for the sanitized, independently verified findings below. Each fixes[] entry MUST bind findingId to the supplied claimId or unique finding id. ' +
    'Only existing authorized manifest paths may be modified automatically. A new regression test is allowed only when explicitly listed in that same finding-bound fix. ' +
    'Do not add new non-test support files. Do not execute repository-controlled scripts or fixer-suggested commands; validation is independent. Return structured observations only.\n\n' +
    JSON.stringify(fixerPayload),
    { tier: 'fixerBig', label: 'fix r' + roundsRun + ' v' + reviewedManifestVersion, schema: fixSchema, retries: 0, timeoutMs: POLICY.fixerTimeoutMs })
  if (!fixResult) {
    for (const finding of fixable) setClaimStatus(finding, 'escalated', roundsRun, 'Fixer failed or timed out; partial working-tree changes may exist.')
    fixerFailure = { round: roundsRun, manifestVersion: reviewedManifestVersion, survivorFindings: fixable, state: 'failed-or-timed-out', timeoutOrFailure: true, partialWorkingTreeChangesMayExist: true }
    const inspection = commandTrust.executionAllowed ? await agent(
      'Inspect the working tree after a failed fixer. This is not a security boundary: do not execute repository-controlled code. Report changed files and return focused validation unavailable.\n\n' + JSON.stringify({ target: fixerPayload.target, claimIds: fixable.map((finding) => finding.claimId) }),
      { tier: 'medium', label: 'validate focused failed fixer r' + roundsRun, schema: focusedValidationSchema, retries: 1, timeoutMs: POLICY.focusedValidationTimeoutMs }) : null
    const safeInspection = inspection ? sanitizeValue(inspection) : null
    const changedFiles = uniq((safeInspection && safeInspection.changedFiles) || [])
    trajectory.push({
      round: roundsRun, manifestVersion: reviewedManifestVersion, manifestVersionAfter: manifestVersion, chunks: roundChunkSummary,
      lanesOk, totalLanes, missingCoverage, everyFileAssigned, genuinelyDry: false, findings: allFindings.length,
      gatedRaw: seriousRaw.length, gated: serious.length, deduplicatedBeforeVerify: seriousRaw.length - serious.length,
      verificationClaims: verificationQueue.length, verificationOverflowCount: overflowFindings.length, verificationOverflow: overflowFindings,
      verified: verifiedThisRound, refuted: refutedThisRound, disputed: disputedThisRound, unverified: unverifiedThisRound,
      escalated: fixable.length + escalatedThisRound, fixesRequested: fixable.length, fixerFailure, fixes: [], changedFiles, testsChanged: [], manifestChanges: [],
      focusedValidation: { status: 'unavailable', applied: null, commands: [], checkedFindingIds: [], notes: 'Fixer failed; inspection cannot confirm success.' },
    })
    fixLog.push({ round: roundsRun, manifestVersion: reviewedManifestVersion, findings: fixable, fixer: null, fixerFailure, focusedValidation: safeInspection, applied: null, focusedTestsStatus: 'unavailable', confirmedFindingIds: [], changedFiles, testsChanged: [], manifestChanges: [], partialWorkingTreeChangesMayExist: true })
    terminationReason = 'fixer-failed-or-timed-out'
    break
  }

  const fix = sanitizeValue(fixResult)
  const validFixesByClaim = Object.create(null)
  const allReportedFixPaths = []
  for (const fixEntry of Array.isArray(fix.fixes) ? fix.fixes : []) {
    const matches = fixable.filter((finding) => bindingMatchesClaim(fixEntry.findingId, finding, fixable))
    if (matches.length !== 1 || validFixesByClaim[matches[0].claimId]) continue
    validFixesByClaim[matches[0].claimId] = fixEntry
    allReportedFixPaths.push(...(fixEntry.files || []), ...(fixEntry.tests || []))
  }
  for (const finding of fixable) {
    if (!validFixesByClaim[finding.claimId]) setClaimStatus(finding, 'escalated', roundsRun, 'Fixer omitted a finding-bound fixes[] entry.')
  }

  const roundManifestChanges = { versionBefore: manifestVersion, versionAfter: manifestVersion, added: [], updated: [], removed: [], outOfPolicy: [], warnings: [] }
  const addPolicyViolation = (path, reason, policy = 'external') => {
    const violation = { round: roundsRun, path: sanitizeText(path), policy, reason: sanitizeText(reason) }
    outOfPolicyChanges.push(violation)
    roundManifestChanges.outOfPolicy.push(violation)
  }
  const manifestByPathBefore = Object.create(null)
  for (const file of manifestFiles) manifestByPathBefore[file.path] = file
  const authorizedPaths = Object.create(null)
  const expectedChangedPaths = Object.create(null)
  for (const finding of fixable) {
    const fixEntry = validFixesByClaim[finding.claimId]
    if (!fixEntry) continue
    const explicitTests = Object.create(null)
    for (const rawTestPath of fixEntry.tests || []) {
      const normalized = normalizeRepoPath(rawTestPath)
      if (!normalized.valid) addPolicyViolation(rawTestPath, 'Fixer reported an unsafe regression-test path.')
      else explicitTests[normalized.path] = true
    }
    const proposed = uniq((fixEntry.files || []).concat(fixEntry.tests || []))
    if (!proposed.length) {
      setClaimStatus(finding, 'escalated', roundsRun, 'Finding-bound fix reported no changed files or tests.')
      continue
    }
    for (const rawPath of proposed) {
      const normalized = normalizeRepoPath(rawPath)
      if (!normalized.valid) {
        addPolicyViolation(rawPath, 'Fixer reported an unsafe or malformed path.')
        continue
      }
      const path = normalized.path
      const existing = manifestByPathBefore[path]
      if (existing && existing.mutationSafe !== false && !(existing.kind === 'symlink' && existing.resolvedPathContained !== true)) {
        authorizedPaths[path] = { kind: 'existing', claimId: finding.claimId }
        expectedChangedPaths[path] = true
      } else if (!existing && explicitTests[path] && isRegressionTestPath(path)) {
        authorizedPaths[path] = { kind: 'regression-test', claimId: finding.claimId }
        expectedChangedPaths[path] = true
      } else {
        addPolicyViolation(path, existing ? 'Path is a symlink or otherwise not mutation-safe.' : 'New non-test support files are not automatically authorized.')
      }
    }
  }
  const expectedPathsList = Object.keys(expectedChangedPaths).sort()

  let validation = null
  if (commandTrust.executionAllowed && Object.keys(validFixesByClaim).length > 0) {
    const focusedPayload = {
      target: { kind: parsedTarget.kind, basis: parsedTarget.basis, selector: parsedTarget.selector, manifestVersion: reviewedManifestVersion },
      claimIds: Object.keys(validFixesByClaim),
      expectedChangedPaths: expectedPathsList,
      suggestedCommands: Array.isArray(fix.focusedTestCommands) ? fix.focusedTestCommands.map(sanitizeText) : [],
    }
    const validationResult = await agent(
      'Independently validate only the listed sanitized claim IDs and expected changed paths. Inspect every command before execution. ' +
      'A passed result requires at least one actually executed passing focused command, no failed/not_run command, and checkedFindingIds for each confirmed claim. ' +
      'If no safe focused command exists, return unavailable. Host execution is not sandboxed.\n\n' + JSON.stringify(focusedPayload),
      { tier: 'medium', label: 'validate focused r' + roundsRun, schema: focusedValidationSchema, retries: 1, timeoutMs: POLICY.focusedValidationTimeoutMs })
    validation = validationResult ? sanitizeValue(validationResult) : null
  }
  const focusedCommands = validation && Array.isArray(validation.commands) ? validation.commands : []
  const focusedHasExecutedPass = focusedCommands.some((command) => command.status === 'passed')
  const focusedHasBadCommand = focusedCommands.some((command) => command.status !== 'passed')
  const focusedPassed = Boolean(validation && validation.applied === true && validation.focusedTestsStatus === 'passed' && focusedCommands.length > 0 && focusedHasExecutedPass && !focusedHasBadCommand)
  const focusedStatus = focusedPassed
    ? 'passed'
    : validation && (validation.focusedTestsStatus === 'failed' || focusedHasBadCommand)
      ? 'failed'
      : 'unavailable'
  const validationChangedFiles = uniq((validation && validation.changedFiles) || [])
  for (const rawPath of validationChangedFiles) {
    const normalized = normalizeRepoPath(rawPath)
    if (!normalized.valid) addPolicyViolation(rawPath, 'Focused validator reported an unsafe changed path.')
    else if (!expectedChangedPaths[normalized.path]) addPolicyViolation(normalized.path, 'Focused validator reported a changed path outside the mechanically expected set.')
  }

  const refreshPayload = {
    target: { kind: parsedTarget.kind, basis: parsedTarget.basis, selector: parsedTarget.selector },
    manifestVersion,
    expectedChangedPaths: expectedPathsList,
    authorizedPaths: Object.keys(authorizedPaths).sort(),
  }
  const refreshResult = await agent(
    'Read-only manifest refresh. Observe actual repository changes independently. The expected and authorized sets are immutable inputs, not suggestions. ' +
    'Return every actual changed path and one file record for every expected path. Extra or omitted paths are out-of-policy/incomplete; policy=allowed cannot expand authorization. ' +
    'Do not execute repository-controlled scripts.\n\n' + JSON.stringify(refreshPayload),
    { tier: 'medium', label: 'refresh manifest r' + roundsRun, schema: refreshSchema, retries: 1, timeoutMs: POLICY.focusedValidationTimeoutMs })
  const refresh = refreshResult ? sanitizeValue(refreshResult) : null
  let refreshRoundComplete = true
  if (!refresh) {
    manifestRefreshIncomplete = true
    refreshRoundComplete = false
    roundManifestChanges.warnings.push('Manifest refresh returned no result.')
  } else {
    const rawActual = uniq(Array.isArray(refresh.actualChangedFiles) ? refresh.actualChangedFiles : [])
    const actualPaths = []
    for (const rawPath of rawActual) {
      const normalized = normalizeRepoPath(rawPath)
      if (!normalized.valid) addPolicyViolation(rawPath, 'Actual changed path is not safely repository-relative.')
      else {
        actualPaths.push(normalized.path)
        if (!expectedChangedPaths[normalized.path]) addPolicyViolation(normalized.path, 'Actual change is outside the mechanically expected set.')
      }
    }
    const refreshByPath = Object.create(null)
    for (const entry of Array.isArray(refresh.files) ? refresh.files : []) {
      const normalized = entry && normalizeRepoPath(entry.path)
      if (!entry || !normalized.valid || !Number.isFinite(entry.lineCount) || entry.lineCount < 0) {
        if (entry && entry.path) addPolicyViolation(entry.path, 'Manifest refresh returned an unsafe or malformed file entry.')
        refreshRoundComplete = false
        continue
      }
      const path = normalized.path
      if (!expectedChangedPaths[path]) {
        addPolicyViolation(path, 'Manifest refresh cannot add a path absent from the expected changed set.', entry.policy)
        continue
      }
      if (!['file', 'symlink', 'other'].includes(entry.kind)) {
        addPolicyViolation(path, 'Manifest refresh did not establish the changed path file kind.')
        refreshRoundComplete = false
        continue
      }
      if (entry.kind === 'other' || (entry.kind === 'symlink' && entry.resolvedPathContained !== true)) {
        addPolicyViolation(path, 'Changed path is not a regular file or a symlink with proven repository containment.')
        continue
      }
      refreshByPath[path] = { ...entry, path, resolvedPathContained: entry.resolvedPathContained === true }
    }
    const missingActual = expectedPathsList.filter((path) => !actualPaths.includes(path))
    const missingEntries = expectedPathsList.filter((path) => !refreshByPath[path])
    if (missingActual.length || missingEntries.length) {
      manifestRefreshIncomplete = true
      refreshRoundComplete = false
      if (missingActual.length) roundManifestChanges.warnings.push('Actual changed-file ledger omitted expected paths: ' + missingActual.join(', '))
      if (missingEntries.length) roundManifestChanges.warnings.push('Manifest refresh omitted expected file entries: ' + missingEntries.join(', '))
    }
    const manifestByPath = Object.create(null)
    for (const file of manifestFiles) manifestByPath[file.path] = file
    for (const path of expectedPathsList) {
      const entry = refreshByPath[path]
      if (!entry) continue
      if (entry.policy !== 'allowed' || !authorizedPaths[path]) {
        addPolicyViolation(path, entry.reason || 'Refresh classified expected path as prohibited.', entry.policy)
        continue
      }
      const existing = manifestByPath[path]
      const authorization = authorizedPaths[path]
      const nextFile = {
        path,
        lineCount: Math.floor(entry.lineCount),
        role: sanitizeText(entry.role || (authorization.kind === 'regression-test' ? 'test' : 'supporting')),
        reason: sanitizeText(entry.reason || 'Changed by a verified finding-bound fix.'),
        selected: Boolean(existing && existing.selected),
        kind: entry.kind,
        resolvedPathContained: entry.resolvedPathContained,
        mutationSafe: entry.kind === 'file' || (entry.kind === 'symlink' && entry.resolvedPathContained === true),
      }
      if (!existing) {
        manifestByPath[path] = nextFile
        roundManifestChanges.added.push(path)
      } else if (existing.lineCount !== nextFile.lineCount || existing.role !== nextFile.role || existing.reason !== nextFile.reason || actualPaths.includes(path)) {
        manifestByPath[path] = { ...existing, ...nextFile }
        roundManifestChanges.updated.push(path)
      }
    }
    roundManifestChanges.updated = uniq(roundManifestChanges.updated)
    if (roundManifestChanges.added.length || roundManifestChanges.updated.length) {
      manifestVersion++
      manifestFiles = Object.keys(manifestByPath).sort().map((path) => manifestByPath[path])
      targetPlan = { ...targetPlan, files: manifestFiles }
      chunkState = buildChunks(manifestFiles, parsedTarget.basis)
      roundManifestChanges.versionAfter = manifestVersion
      manifestChanges.push({ version: manifestVersion, round: roundsRun, added: roundManifestChanges.added, updated: roundManifestChanges.updated, removed: [], reason: 'post-fix manifest refresh' })
      if (!chunkState.complete) {
        coverageLimitExceeded = true
        terminationReason = 'coverage-limit-exceeded-after-refresh'
      }
    }
    roundManifestChanges.warnings.push(...(Array.isArray(refresh.warnings) ? refresh.warnings.map(sanitizeText) : []))
  }

  const confirmedFindingIds = []
  const checkedIds = validation && Array.isArray(validation.checkedFindingIds) ? validation.checkedFindingIds.map(sanitizeText) : []
  for (const finding of fixable) {
    const fixEntry = validFixesByClaim[finding.claimId]
    const checked = checkedIds.some((id) => bindingMatchesClaim(id, finding, fixable))
    const fixPaths = fixEntry ? uniq((fixEntry.files || []).concat(fixEntry.tests || [])).map((path) => normalizeRepoPath(path)).filter((entry) => entry.valid).map((entry) => entry.path) : []
    const changedFilesConsistent = fixPaths.length > 0 && fixPaths.every((path) => validationChangedFiles.map((entry) => normalizeRepoPath(entry)).some((entry) => entry.valid && entry.path === path))
    const confirmed = Boolean(fixEntry && checked && focusedPassed && changedFilesConsistent && refreshRoundComplete && !roundManifestChanges.outOfPolicy.length)
    if (confirmed) {
      setClaimStatus(finding, 'fixed-and-validated', roundsRun, 'Finding-bound fix and focused command evidence were confirmed.')
      resolveOverflow(finding.claimId, 'fixed-and-validated', roundsRun)
      confirmedFindingIds.push(finding.claimId)
    } else if (seriousClaims[finding.claimId].status !== 'escalated') {
      setClaimStatus(finding, 'escalated', roundsRun, 'Fix or focused validation was missing, inconsistent, unsafe, or incomplete.')
      resolveOverflow(finding.claimId, 'escalated', roundsRun)
    }
  }
  if (outOfPolicyChanges.length) terminationReason = 'out-of-policy-fixer-changes'

  const reportedChangedFiles = uniq(allReportedFixPaths.concat(validationChangedFiles)).map(sanitizeText)
  const testsChanged = uniq(Object.values(validFixesByClaim).flatMap((entry) => entry.tests || [])).map(sanitizeText)
  trajectory.push({
    round: roundsRun, manifestVersion: reviewedManifestVersion, manifestVersionAfter: manifestVersion, chunks: roundChunkSummary,
    lanesOk, totalLanes, missingCoverage, everyFileAssigned, genuinelyDry: false, findings: allFindings.length,
    gatedRaw: seriousRaw.length, gated: serious.length, deduplicatedBeforeVerify: seriousRaw.length - serious.length,
    verificationClaims: verificationQueue.length, verificationOverflowCount: overflowFindings.length, verificationOverflow: overflowFindings,
    verified: verifiedThisRound, refuted: refutedThisRound, disputed: disputedThisRound, unverified: unverifiedThisRound,
    escalated: escalatedThisRound + fixable.length - confirmedFindingIds.length, fixesRequested: fixable.length,
    fixSummary: fix.summary, fixes: fix.fixes || [], changedFiles: reportedChangedFiles, testsChanged, manifestChanges: roundManifestChanges,
    focusedValidation: { status: focusedStatus, applied: validation ? validation.applied : null, commands: focusedCommands, checkedFindingIds: checkedIds, confirmedFindingIds, notes: validation ? validation.notes : commandTrust.reason },
  })
  fixLog.push({
    round: roundsRun, manifestVersion: reviewedManifestVersion, manifestVersionAfter: manifestVersion, findings: fixable, fixer: fix,
    focusedValidation: validation, applied: validation ? validation.applied : null, focusedTestsStatus: focusedStatus,
    confirmedFindingIds, changedFiles: reportedChangedFiles, testsChanged, manifestChanges: roundManifestChanges, partialWorkingTreeChangesMayExist: false,
  })
}

if (fixerFailure) terminationReason = 'fixer-failed-or-timed-out'
else if (outOfPolicyChanges.length) terminationReason = 'out-of-policy-fixer-changes'
else if (coverageLimitExceeded && terminationReason === 'round-cap') terminationReason = 'coverage-limit-exceeded'
else if (convergedDry >= POLICY.consecutiveDryRounds) terminationReason = 'consecutive-clean-rounds'
else if (terminationReason === 'round-cap') terminationReason = 'round-cap'

for (const entry of Object.values(seriousClaims)) {
  if (entry.status === 'pending' || entry.status === 'verified') {
    entry.status = 'unverified'
    entry.reason = entry.reason || 'Claim did not reach a terminal adjudication before the workflow stopped.'
    entry.terminalRound = roundsRun
  }
  if (entry.status === 'fixed-and-validated' && entry.recurredAfterFix && entry.lastSeenRound === roundsRun) {
    entry.status = 'escalated'
    entry.reason = 'Claim recurred after a reported fix and no later dry round proved it absent.'
    entry.terminalRound = roundsRun
  }
}

phase('Final Validation')
const trackedUnique = dedupBy(tracked, reportKeyOf)
const seriousLedger = Object.values(seriousClaims).sort((left, right) => left.claimId < right.claimId ? -1 : (left.claimId > right.claimId ? 1 : 0)).map((entry) => ({
  claimId: entry.claimId,
  status: entry.status,
  reason: entry.reason,
  firstSeenRound: entry.firstSeenRound,
  lastSeenRound: entry.lastSeenRound,
  terminalRound: entry.terminalRound,
  finding: entry.finding,
}))
const claimsWithStatus = (status) => seriousLedger.filter((entry) => entry.status === status).map((entry) => ({ ...entry.finding, adjudication: status, adjudicationReason: entry.reason }))
const refutedUnique = claimsWithStatus('refuted')
const unverifiedUnique = claimsWithStatus('unverified')
const disputedUnique = claimsWithStatus('disputed')
const escalatedUnique = claimsWithStatus('escalated')
const fixedUnique = claimsWithStatus('fixed-and-validated')
const verifiedUnique = seriousLedger.filter((entry) => seriousClaims[entry.claimId].everVerified).map((entry) => ({ ...entry.finding, adjudication: entry.status }))
const unresolvedSerious = escalatedUnique.concat(disputedUnique, unverifiedUnique)
const pendingVerificationOverflow = verificationOverflow.filter((entry) => entry.status === 'pending')
const totalAddressed = Object.keys(addressedClaimIds).length
const totalResolved = fixedUnique.length
const terminalRounds = trajectory.slice(-POLICY.consecutiveDryRounds)
const terminalManifestCovered = terminalRounds.length === POLICY.consecutiveDryRounds && terminalRounds.every((entry) =>
  entry.genuinelyDry && entry.manifestVersion === manifestVersion && entry.manifestVersionAfter === manifestVersion && entry.lanesOk === entry.totalLanes && entry.totalLanes > 0 && entry.everyFileAssigned)
const currentAssignedPaths = uniq(chunkState.chunks.flatMap((chunk) => chunk.map((file) => file.path))).sort()
const currentManifestPaths = manifestFiles.map((file) => file.path).sort()
const everySelectedFileAssigned = chunkState.complete && currentAssignedPaths.length === currentManifestPaths.length && currentAssignedPaths.every((path, index) => path === currentManifestPaths[index])
const unconfirmedFixes = fixLog.filter((entry) => (entry.findings || []).length !== (entry.confirmedFindingIds || []).length)
const manifestChangedAfterFinalCoveredRound = !trajectory.length || trajectory[trajectory.length - 1].manifestVersionAfter !== manifestVersion || trajectory[trajectory.length - 1].manifestVersion !== manifestVersion
const coverageComplete = terminalManifestCovered && everySelectedFileAssigned && !coverageLimitExceeded && missingCriticLanes.length === 0
const converged = convergedDry >= POLICY.consecutiveDryRounds
const convergenceCandidate = manifestFiles.length > 0 && discovery.complete && coverageComplete && converged && !manifestChangedAfterFinalCoveredRound &&
  !fixerFailure && !manifestRefreshIncomplete && !outOfPolicyChanges.length && unresolvedSerious.length === 0 &&
  pendingVerificationOverflow.length === 0 && unconfirmedFixes.length === 0
const finalValidationEligible = convergenceCandidate && commandTrust.executionAllowed
const normalizeFinalValidation = (result) => {
  if (!result) return { status: 'unavailable', commands: [], summary: 'Final validation returned no result.', failures: ['Missing final validation coverage.'], reason: 'validator-null' }
  const safe = sanitizeValue(result)
  const commands = Array.isArray(safe.commands) ? safe.commands : []
  const failures = Array.isArray(safe.failures) ? safe.failures.map(sanitizeText) : []
  const requiredCommands = commands.filter((command) => command.required !== false)
  const anyFailed = commands.some((command) => command.status === 'failed')
  const anyNotRun = commands.some((command) => command.status === 'not_run')
  const everyRequiredPassed = requiredCommands.length > 0 && requiredCommands.every((command) => command.status === 'passed')
  if (safe.status === 'failed' || anyFailed || failures.length) {
    return { ...safe, status: 'failed', commands, failures, reason: anyFailed ? 'command-failed' : failures.length ? 'reported-failures' : 'validator-failed' }
  }
  if (safe.status !== 'passed') {
    return { ...safe, status: 'unavailable', commands, failures, reason: safe.reason || 'validator-unavailable' }
  }
  if (!commands.length) return { ...safe, status: 'unavailable', commands, failures, reason: 'empty-command-ledger' }
  if (!requiredCommands.length) return { ...safe, status: 'unavailable', commands, failures, reason: 'no-required-canonical-command' }
  if (anyNotRun) return { ...safe, status: 'unavailable', commands, failures, reason: 'required-command-not-run' }
  if (!everyRequiredPassed || commands.some((command) => command.status !== 'passed')) {
    return { ...safe, status: 'failed', commands, failures, reason: 'inconsistent-command-ledger' }
  }
  return { ...safe, status: 'passed', commands, failures, reason: 'all-required-commands-passed' }
}
let finalValidation = {
  status: 'skipped', commands: [], summary: 'Full validation skipped because the target did not reach a complete convergence candidate.', failures: [],
  reason: fixerFailure ? 'fixer-failed-or-timed-out'
    : outOfPolicyChanges.length ? 'out-of-policy-fixer-changes'
      : coverageLimitExceeded ? 'coverage-limit-exceeded'
        : !discovery.complete ? 'incomplete-target-discovery'
          : manifestRefreshIncomplete ? 'manifest-refresh-incomplete'
            : pendingVerificationOverflow.length ? 'verification-overflow'
              : unresolvedSerious.length ? 'unresolved-serious-findings'
                : !coverageComplete ? 'incomplete-critic-coverage'
                  : 'not-converged',
}
if (convergenceCandidate && !commandTrust.executionAllowed) {
  finalValidation = { status: 'unavailable', commands: [], summary: commandTrust.reason, failures: [], reason: 'untrusted-target-without-enforceable-isolation' }
} else if (finalValidationEligible) {
  const finalPayload = {
    target: { kind: parsedTarget.kind, basis: parsedTarget.basis, selector: parsedTarget.selector },
    manifestVersion,
    manifestPaths: manifestFiles.map((file) => file.path),
    confirmedClaimIds: fixedUnique.map((finding) => finding.claimId),
    commandTrust,
  }
  const finalResult = await agent(
    'Final validator for a locally authorized target. Discover canonical validation from repository docs, scripts, and CI. Host execution is not sandboxed. ' +
    'Run the canonical full test/build/typecheck commands needed for this target exactly once. Mark canonical commands required=true. ' +
    'Passed requires a non-empty ledger, at least one required command, every command actually run and passed, and no failures. Otherwise return failed or unavailable.\n\n' +
    JSON.stringify(finalPayload),
    { tier: 'medium', label: 'final validation', schema: finalValidationSchema, retries: 0, timeoutMs: POLICY.finalValidationTimeoutMs })
  finalValidation = normalizeFinalValidation(finalResult)
}

const verdict = fixerFailure
  ? 'INCONCLUSIVE - fixer failed or timed out; inspect partial working-tree changes'
  : outOfPolicyChanges.length
    ? 'INCONCLUSIVE - fixer changed files outside the target mutation policy'
    : coverageLimitExceeded
      ? 'INCONCLUSIVE - target exceeds coverage limit'
      : !discovery.complete
        ? 'INCONCLUSIVE - target discovery is incomplete'
        : manifestRefreshIncomplete
          ? 'INCONCLUSIVE - post-fix manifest refresh is incomplete'
          : pendingVerificationOverflow.length
            ? 'INCONCLUSIVE - unresolved verification overflow (' + pendingVerificationOverflow.length + ' claim(s))'
            : escalatedUnique.length
              ? 'CONVERGED WITH ESCALATED OR UNCONFIRMED SERIOUS FINDINGS - ' + escalatedUnique.length + ' need human action'
              : disputedUnique.length
                ? 'CONVERGED WITH DISPUTED FINDINGS - ' + disputedUnique.length + ' need human review'
                : unverifiedUnique.length
                  ? 'CONVERGED WITH UNVERIFIED FINDINGS - ' + unverifiedUnique.length + ' need human review'
                  : !converged
                    ? 'STOPPED AT CAP - did not reach ' + POLICY.consecutiveDryRounds + ' consecutive dry rounds on the current manifest'
                    : !coverageComplete
                      ? 'INCONCLUSIVE - incomplete critic coverage'
                      : unconfirmedFixes.length
                        ? 'CONVERGED WITH UNCONFIRMED FOCUSED VALIDATION - ' + unconfirmedFixes.length + ' fix round(s) need review'
                        : manifestChangedAfterFinalCoveredRound
                          ? 'INCONCLUSIVE - manifest changed after the final covered round'
                          : finalValidation.status === 'failed'
                            ? 'CONVERGED BUT FINAL FULL VALIDATION FAILED'
                            : finalValidation.status !== 'passed'
                              ? 'CONVERGED BUT FINAL FULL VALIDATION UNAVAILABLE'
                              : 'CONVERGED CLEAN'
const efficiency = {
  criticLaneCalls: chunkCoverage.reduce((total, entry) => total + entry.totalLanes, 0),
  verificationClaims,
  verificationVotesRequested: verificationClaims * POLICY.reviewers,
  verificationOverflowClaims: verificationOverflow.length,
  unresolvedVerificationOverflowClaims: pendingVerificationOverflow.length,
  duplicateVerificationClaimsSkipped: verificationDedupSavings,
  focusedValidationRounds: fixLog.length,
  focusedValidationCommands: fixLog.reduce((total, entry) => total + ((entry.focusedValidation && entry.focusedValidation.commands || []).filter((command) => command.status === 'passed' || command.status === 'failed').length), 0),
  finalFullValidationRuns: finalValidationEligible ? 1 : 0,
}

phase('Report')
const synthesisPayload = sanitizeValue({
  verdict,
  parsedTarget,
  targetPlan: { kind: targetPlan.kind, basis: targetPlan.basis, label: targetPlan.label, selector: targetPlan.selector, fileCount: manifestFiles.length },
  discovery: { complete: discovery.complete, evidence: discovery.evidence, exclusions: discovery.exclusions, warnings: discovery.warnings, disagreements: discovery.disagreements },
  manifestVersion,
  manifestPaths: manifestFiles.map((file) => file.path),
  manifestChanges,
  chunkCoverage,
  routing,
  limits,
  trajectory: trajectory.map((entry) => ({
    round: entry.round, manifestVersion: entry.manifestVersion, manifestVersionAfter: entry.manifestVersionAfter,
    lanesOk: entry.lanesOk, totalLanes: entry.totalLanes, missingCoverage: entry.missingCoverage,
    genuinelyDry: entry.genuinelyDry, findings: entry.findings, verificationClaims: entry.verificationClaims,
    verificationOverflowCount: entry.verificationOverflowCount, verified: entry.verified, refuted: entry.refuted,
    disputed: entry.disputed, unverified: entry.unverified, escalated: entry.escalated,
    confirmedFindingIds: entry.focusedValidation && entry.focusedValidation.confirmedFindingIds || [],
  })),
  claims: seriousLedger.map((entry) => ({
    claimId: entry.claimId, status: entry.status, reason: entry.reason,
    severity: entry.finding.severity, category: entry.finding.category, canonicalPath: entry.finding.canonicalPath,
    location: entry.finding.location, description: entry.finding.description,
  })),
  tracked: trackedUnique.map((finding) => ({ severity: finding.severity, category: finding.category, canonicalPath: finding.canonicalPath, location: finding.location, description: finding.description })),
  finalValidation,
  outOfPolicyChanges,
  missingCriticLanes,
  commandTrust,
  residualRisk,
  efficiency,
})
const reportResult = await agent(
  'Write an evidence-rich, scannable TARGET-AWARE review report from this compact sanitized payload. Preserve the mechanical verdict and every serious terminal state. ' +
  'Include manifestChanges, chunkCoverage, missing critic lanes/timeouts, final validation, command-trust limitations, and residual risk. ' +
  'Do not invent secret values or claim that prompt wording, Git refresh, or best-effort worktrees are a sandbox.\n\n' + JSON.stringify(synthesisPayload),
  { tier: 'medium', label: 'synthesis' })
const report = sanitizeText(reportResult || 'Report synthesis returned no result.')

return {
  verdict,
  terminationReason,
  parsedTarget,
  targetPlan,
  targetManifest: { version: manifestVersion, files: manifestFiles, fileCount: manifestFiles.length, totalLines: sumLines(manifestFiles) },
  discovery,
  manifestChanges,
  roundsRun,
  chunks: chunkState.chunks.length,
  chunkSummary: summarizeChunks(chunkState),
  chunkCoverage,
  skippedCoverage: chunkState.skippedCoverage,
  oversizedFiles: chunkState.oversizedFiles,
  limits,
  routing,
  totalAddressed,
  totalResolved,
  totalFixed: totalResolved,
  unresolved: unresolvedSerious,
  verified: verifiedUnique,
  refuted: refutedUnique,
  unverified: unverifiedUnique,
  disputed: disputedUnique,
  escalated: escalatedUnique,
  tracked: trackedUnique,
  seriousLedger,
  verificationOverflow,
  verificationOverflowCount: verificationOverflow.length,
  unresolvedVerificationOverflow: pendingVerificationOverflow,
  unresolvedVerificationOverflowCount: pendingVerificationOverflow.length,
  outOfPolicyChanges,
  fixerFailure,
  trajectory,
  fixLog,
  finalValidation,
  coverageComplete,
  manifestChangedAfterFinalCoveredRound,
  missingCriticLanes,
  commandTrust,
  residualRisk,
  efficiency,
  report,
}
